import { Component, Input, Output, EventEmitter } from '@angular/core';

interface ContactFormSubmitPayload {
  name: string;
  email: string;
  message: string;
}

interface ContactFormValidationFailedPayload {
  fields: string[];
}

@Component({
  selector: 'app-contact-form',
  standalone: true,
  template: `
    <div class="contact-form">
      <h2>Kontaktformular</h2>

      <div class="field">
        <label for="cf-name">Name</label>
        <input
          id="cf-name"
          type="text"
          [value]="name"
          (input)="onNameInput($any($event.target).value)"
          [disabled]="submitting"
        />
        <span class="debug">initial_name: {{ initial_name }}</span>
      </div>

      <div class="field">
        <label for="cf-email">E-Mail</label>
        <input
          id="cf-email"
          type="email"
          [value]="email"
          (input)="onEmailInput($any($event.target).value)"
          [disabled]="submitting"
        />
        <span class="debug">initial_email: {{ initial_email }}</span>
      </div>

      <div class="field">
        <label for="cf-message">Nachricht</label>
        <textarea
          id="cf-message"
          [value]="message"
          (input)="onMessageInput($any($event.target).value)"
          [disabled]="submitting"
        ></textarea>
      </div>

      <div class="field">
        <span class="debug">submitting: {{ submitting }}</span>
      </div>

      <div class="error" *ngIf="server_error">
        <span>{{ server_error }}</span>
      </div>

      <button type="button" (click)="onSubmit()" [disabled]="submitting">
        <span *ngIf="!submitting">Senden</span>
        <span *ngIf="submitting">Wird gesendet...</span>
      </button>
    </div>
  `,
  styles: [`
    .contact-form {
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
      max-width: 480px;
      font-family: sans-serif;
    }
    .field {
      display: flex;
      flex-direction: column;
      gap: 0.25rem;
    }
    .field label {
      font-weight: 600;
    }
    .field input,
    .field textarea {
      padding: 0.5rem;
      border: 1px solid #ccc;
      border-radius: 4px;
      font: inherit;
    }
    .field textarea {
      min-height: 6rem;
      resize: vertical;
    }
    .debug {
      font-size: 0.75rem;
      color: #888;
    }
    .error {
      color: #b00020;
      font-weight: 600;
    }
    button {
      padding: 0.6rem 1rem;
      border: none;
      border-radius: 4px;
      background: #1976d2;
      color: #fff;
      cursor: pointer;
      font-weight: 600;
    }
    button[disabled] {
      opacity: 0.6;
      cursor: not-allowed;
    }
  `]
})
export class ContactFormComponent {
  @Input() initial_name?: string;
  @Input() initial_email?: string;
  @Input() submitting: boolean = false;
  @Input() server_error?: string;

  @Output() submit = new EventEmitter<ContactFormSubmitPayload>();
  @Output() validation_failed = new EventEmitter<ContactFormValidationFailedPayload>();

  name: string = '';
  email: string = '';
  message: string = '';

  private _initialized: boolean = false;

  ngOnChanges(): void {
    if (!this._initialized) {
      if (typeof this.initial_name === 'string') {
        this.name = this.initial_name;
      }
      if (typeof this.initial_email === 'string') {
        this.email = this.initial_email;
      }
      this._initialized = true;
    }
  }

  onNameInput(value: string): void {
    this.name = value;
  }

  onEmailInput(value: string): void {
    this.email = value;
  }

  onMessageInput(value: string): void {
    this.message = value;
  }

  onSubmit(): void {
    if (this.submitting) {
      return;
    }

    const invalidFields: string[] = [];

    const trimmedName = (this.name || '').trim();
    if (trimmedName.length === 0) {
      invalidFields.push('name');
    }

    const trimmedEmail = (this.email || '').trim();
    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (trimmedEmail.length === 0 || !emailPattern.test(trimmedEmail)) {
      invalidFields.push('email');
    }

    const trimmedMessage = (this.message || '').trim();
    if (trimmedMessage.length < 10) {
      invalidFields.push('message');
    }

    if (invalidFields.length > 0) {
      this.validation_failed.emit({ fields: invalidFields });
      return;
    }

    this.submit.emit({
      name: trimmedName,
      email: trimmedEmail,
      message: trimmedMessage
    });
  }
}
